function [o] = dtm_profile(set, gd_tt, gd_t0, gd_tp, gd_sp, alti)
%DTM_PROFILE  The Bates temperature profile and the diffusive integration of the six species, shared by dtm3 and dtm5, given the
%   nine gdel (tt, t0, tp, then H, He, O, N2, O2, N) and the altitude [km].
%   set: DtmSet (passed a choice, as its option's number)
%   gd_tt: real[1] (passed a plain number)
%   gd_t0: real[1] (passed a plain number)
%   gd_tp: real[1] (passed a plain number)
%   gd_sp: real[1][6] (passed a plain number)
%   alti: real[1] (passed a plain number)
%   returns o: DtmRaw (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    o = asils.models.dtm2020.DtmRaw_zero();
    ma = [1; 4; 16; 28; 32; 14];
    alefa = [(-(0.4)); (-(0.38)); 0; 0; 0; 0];
    vma = asils.models.dtm2020.dtm_vma();
    tt = asils.models.dtm2020.dtm_column(set, 0);
    t0 = asils.models.dtm2020.dtm_column(set, 7);
    tp = asils.models.dtm2020.dtm_column(set, 8);
    zlb = 120;
    tinf = (tt(2) * (1 + gd_tt));
    t120 = (t0(2) * (1 + gd_t0));
    tp120 = (tp(2) * (1 + gd_tp));
    sigma = (tp120 / (tinf - t120));
    dzeta = ((6356.77 + zlb) / (6356.77 + alti));
    zeta = ((alti - zlb) * dzeta);
    sigzeta = (sigma * zeta);
    expsz = exp((-(sigzeta)));
    tz = (tinf - ((tinf - t120) * expsz));
    dbase = zeros(6, 1);
    for i = (0):((6) - 1)
        sp = asils.models.dtm2020.dtm_column(set, (i + 1));
        dbase((i) + 1) = (sp(2) * exp(gd_sp((i) + 1)));
    end
    glb = (980.665 / asils.pc.pow_((1 + (zlb / 6356.77)), 2));
    glb = (glb / ((sigma * 831.4) * tinf));
    t120tz = (t120 / tz);
    o = asils.models.dtm2020.DtmRaw_zero();
    cc = zeros(6, 1);
    ro = 0;
    for i = (0):((6) - 1)
        gamma = (ma((i) + 1) * glb);
        upapg = ((1 + alefa((i) + 1)) + gamma);
        fz_i = (asils.pc.pow_(t120tz, upapg) * exp(((-(sigzeta)) * gamma)));
        cc((i) + 1) = (dbase((i) + 1) * fz_i);
        o.d((i) + 1) = (cc((i) + 1) * vma((i) + 1));
        ro = (ro + o.d((i) + 1));
    end
    sum_cc = 0;
    for i = (0):((6) - 1)
        sum_cc = (sum_cc + cc((i) + 1));
    end
    o.tz = tz;
    o.tinf = tinf;
    o.ro = ro;
    o.wmm = (ro / (vma(1) * sum_cc));
end
